CREATE TABLE IF NOT EXISTS "teacher_credentials" (
  "title" TEXT NOT NULL,
  "issuer" TEXT NOT NULL,
  "year" TEXT NOT NULL,
  "image" TEXT NOT NULL,
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_credentials_teacherId" ON "teacher_credentials" ("teacherId");

-- teacher_evidence

CREATE TABLE IF NOT EXISTS "teacher_evidence" (
  "type" TEXT NOT NULL,
  "caption" TEXT NOT NULL,
  "image" TEXT NOT NULL,
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_evidence_teacherId" ON "teacher_evidence" ("teacherId");

-- teacher_reviewlist

CREATE TABLE IF NOT EXISTS "teacher_reviewlist" (
  "name" TEXT NOT NULL,
  "star" INTEGER NOT NULL,
  "text" TEXT NOT NULL,
  "date" TEXT NOT NULL,
  "images" TEXT CHECK ("images" IS NULL OR json_valid("images")),
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_reviewlist_teacherId" ON "teacher_reviewlist" ("teacherId");

-- teacher_education

CREATE TABLE IF NOT EXISTS "teacher_education" (
  "school" TEXT NOT NULL,
  "degree" TEXT NOT NULL,
  "major" TEXT NOT NULL,
  "years" TEXT NOT NULL,
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_education_teacherId" ON "teacher_education" ("teacherId");

-- teacher_experience

CREATE TABLE IF NOT EXISTS "teacher_experience" (
  "role" TEXT NOT NULL,
  "org" TEXT NOT NULL,
  "years" TEXT NOT NULL,
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_experience_teacherId" ON "teacher_experience" ("teacherId");

-- teacher_students

CREATE TABLE IF NOT EXISTS "teacher_students" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "course" TEXT NOT NULL,
  "progress" TEXT NOT NULL,
  "nextLesson" TEXT,
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "courseId" TEXT REFERENCES "teacher_courses"("id"),
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_students_teacherId" ON "teacher_students" ("teacherId");

CREATE INDEX IF NOT EXISTS "idx_teacher_students_courseId" ON "teacher_students" ("courseId");

-- teacher_lessons

CREATE TABLE IF NOT EXISTS "teacher_lessons" (
  "id" TEXT PRIMARY KEY,
  "studentName" TEXT NOT NULL,
  "courseTitle" TEXT NOT NULL,
  "date" TEXT NOT NULL,
  "startTime" TEXT NOT NULL,
  "endTime" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('待上', '已完成', '已取消')),
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "courseId" TEXT REFERENCES "teacher_courses"("id"),
  "studentId" TEXT REFERENCES "teacher_students"("id"),
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_lessons_teacherId" ON "teacher_lessons" ("teacherId");

CREATE INDEX IF NOT EXISTS "idx_teacher_lessons_courseId" ON "teacher_lessons" ("courseId");

CREATE INDEX IF NOT EXISTS "idx_teacher_lessons_studentId" ON "teacher_lessons" ("studentId");

-- teacher_orders

CREATE TABLE IF NOT EXISTS "teacher_orders" (
  "id" TEXT PRIMARY KEY,
  "studentName" TEXT NOT NULL,
  "courseTitle" TEXT NOT NULL,
  "amount" INTEGER NOT NULL,
  "date" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('已支付')),
  "teacherId" TEXT REFERENCES "teacher_profiles"("id"),
  "courseId" TEXT REFERENCES "teacher_courses"("id"),
  "studentId" TEXT REFERENCES "teacher_students"("id"),
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_orders_teacherId" ON "teacher_orders" ("teacherId");

CREATE INDEX IF NOT EXISTS "idx_teacher_orders_courseId" ON "teacher_orders" ("courseId");

CREATE INDEX IF NOT EXISTS "idx_teacher_orders_studentId" ON "teacher_orders" ("studentId");

-- teacher_social_posts

CREATE TABLE IF NOT EXISTS "teacher_social_posts" (
  "id" TEXT PRIMARY KEY,
  "author" TEXT NOT NULL,
  "authorRole" TEXT NOT NULL,
  "authorAvatar" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "image" TEXT,
  "time" TEXT NOT NULL,
  "likes" INTEGER NOT NULL,
  "comments" TEXT NOT NULL CHECK ("comments" IS NULL OR json_valid("comments")),
  "reposts" INTEGER NOT NULL,
  "liked" INTEGER NOT NULL CHECK ("liked" IN (0, 1) OR "liked" IS NULL),
  "reposted" INTEGER NOT NULL CHECK ("reposted" IN (0, 1) OR "reposted" IS NULL),
  "_seedOrigin" TEXT
);

-- teacher_social_comments

CREATE TABLE IF NOT EXISTS "teacher_social_comments" (
  "id" TEXT PRIMARY KEY,
  "author" TEXT NOT NULL,
  "avatar" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "time" TEXT NOT NULL,
  "likes" INTEGER NOT NULL,
  "postId" TEXT REFERENCES "teacher_social_posts"("id"),
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_social_comments_postId" ON "teacher_social_comments" ("postId");

-- teacher_connections

CREATE TABLE IF NOT EXISTS "teacher_connections" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "avatar" TEXT NOT NULL,
  "mutualConnections" INTEGER NOT NULL,
  "connected" INTEGER NOT NULL CHECK ("connected" IN (0, 1) OR "connected" IS NULL),
  "pending" INTEGER NOT NULL CHECK ("pending" IN (0, 1) OR "pending" IS NULL),
  "userId" TEXT REFERENCES "users"("id"),
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_connections_userId" ON "teacher_connections" ("userId");

-- admin_roles

CREATE TABLE IF NOT EXISTS "admin_roles" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT,
  "_seedOrigin" TEXT
);

-- 禁用的演示账号，不写入前端明文凭据或会话 token

CREATE TABLE IF NOT EXISTS "admin_accounts" (
  "id" TEXT PRIMARY KEY,
  "role" TEXT REFERENCES "admin_roles"("id"),
  "name" TEXT,
  "email" TEXT,
  "enabled" INTEGER CHECK ("enabled" IN (0, 1) OR "enabled" IS NULL),
  "passwordHash" TEXT,
  "_seedOrigin" TEXT,
  UNIQUE ("email")
);

CREATE INDEX IF NOT EXISTS "idx_admin_accounts_role" ON "admin_accounts" ("role");

-- admin_users

CREATE TABLE IF NOT EXISTS "admin_users" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('active', 'muted', 'banned')),
  "joinedAt" TEXT NOT NULL,
  "bio" TEXT NOT NULL,
  "posts" INTEGER NOT NULL,
  "mutedUntil" TEXT,
  "resetRequested" INTEGER NOT NULL CHECK ("resetRequested" IN (0, 1) OR "resetRequested" IS NULL),
  "_seedOrigin" TEXT,
  UNIQUE ("email")
);

-- teacher_applications

CREATE TABLE IF NOT EXISTS "teacher_applications" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL REFERENCES "admin_users"("id"),
  "name" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "institution" TEXT NOT NULL,
  "experience" TEXT NOT NULL,
  "resume" TEXT NOT NULL,
  "qualification" TEXT NOT NULL,
  "submittedAt" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('pending', 'approved', 'rejected')),
  "reason" TEXT,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_teacher_applications_userId" ON "teacher_applications" ("userId");

-- post_approvals

CREATE TABLE IF NOT EXISTS "post_approvals" (
  "id" TEXT PRIMARY KEY,
  "authorId" TEXT NOT NULL REFERENCES "admin_users"("id"),
  "author" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "submittedAt" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('pending', 'approved', 'rejected', 'removed')),
  "views" INTEGER NOT NULL,
  "likes" INTEGER NOT NULL,
  "reason" TEXT,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_post_approvals_authorId" ON "post_approvals" ("authorId");

-- 为已有举报中 c1/c3 目标补充演示评论

CREATE TABLE IF NOT EXISTS "moderation_comments" (
  "id" TEXT PRIMARY KEY,
  "authorId" TEXT REFERENCES "admin_users"("id"),
  "content" TEXT,
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_moderation_comments_authorId" ON "moderation_comments" ("authorId");

-- reports

CREATE TABLE IF NOT EXISTS "reports" (
  "id" TEXT PRIMARY KEY,
  "type" TEXT NOT NULL CHECK ("type" IN ('post', 'comment')),
  "targetId" TEXT NOT NULL,
  "authorId" TEXT NOT NULL REFERENCES "admin_users"("id"),
  "author" TEXT NOT NULL,
  "reporter" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "submittedAt" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('pending', 'ignored', 'removed', 'punished')),
  "resolution" TEXT,
  "postId" TEXT REFERENCES "post_approvals"("id"),
  "commentId" TEXT REFERENCES "moderation_comments"("id"),
  "_seedOrigin" TEXT,
  CHECK (("type" = 'post' AND "postId" IS NOT NULL AND "commentId" IS NULL) OR ("type" = 'comment' AND "commentId" IS NOT NULL AND "postId" IS NULL))
);

CREATE INDEX IF NOT EXISTS "idx_reports_authorId" ON "reports" ("authorId");

CREATE INDEX IF NOT EXISTS "idx_reports_postId" ON "reports" ("postId");

CREATE INDEX IF NOT EXISTS "idx_reports_commentId" ON "reports" ("commentId");

-- audit_logs

CREATE TABLE IF NOT EXISTS "audit_logs" (
  "id" TEXT PRIMARY KEY,
  "operator" TEXT NOT NULL,
  "time" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "target" TEXT NOT NULL,
  "detail" TEXT NOT NULL,
  "violation" INTEGER NOT NULL CHECK ("violation" IN (0, 1) OR "violation" IS NULL),
  "_seedOrigin" TEXT
);

-- admin_settings

CREATE TABLE IF NOT EXISTS "admin_settings" (
  "preModeration" INTEGER NOT NULL CHECK ("preModeration" IN (0, 1) OR "preModeration" IS NULL),
  "notifyReports" INTEGER NOT NULL CHECK ("notifyReports" IN (0, 1) OR "notifyReports" IS NULL),
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

-- resetRequested 对应演示请求，不生成重置 token

CREATE TABLE IF NOT EXISTS "password_reset_requests" (
  "userId" TEXT REFERENCES "admin_users"("id"),
  "status" TEXT,
  "requestedAt" TEXT,
  "_seedOrigin" TEXT,
  "id" TEXT PRIMARY KEY
);

CREATE INDEX IF NOT EXISTS "idx_password_reset_requests_userId" ON "password_reset_requests" ("userId");

-- ted_talks

CREATE TABLE IF NOT EXISTS "ted_talks" (
  "id" TEXT PRIMARY KEY,
  "title" TEXT NOT NULL,
  "author" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "categoryColor" TEXT,
  "duration" TEXT NOT NULL,
  "plays" TEXT,
  "thumbnail" TEXT NOT NULL,
  "href" TEXT,
  "videoUrl" TEXT,
  "description" TEXT,
  "section" TEXT,
  "_seedOrigin" TEXT
);

-- ted_featured_talks

CREATE TABLE IF NOT EXISTS "ted_featured_talks" (
  "category" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "author" TEXT NOT NULL,
  "meta" TEXT NOT NULL,
  "duration" TEXT NOT NULL,
  "thumbnail" TEXT NOT NULL,
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

-- ted_trending_categories

CREATE TABLE IF NOT EXISTS "ted_trending_categories" (
  "id" TEXT PRIMARY KEY,
  "label" TEXT NOT NULL,
  "color" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "talks" TEXT NOT NULL CHECK ("talks" IS NULL OR json_valid("talks")),
  "_seedOrigin" TEXT
);

-- newsletters

CREATE TABLE IF NOT EXISTS "newsletters" (
  "id" TEXT PRIMARY KEY,
  "frequency" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "_seedOrigin" TEXT
);

-- portfolio_nav

CREATE TABLE IF NOT EXISTS "portfolio_nav" (
  "id" TEXT PRIMARY KEY,
  "label" TEXT,
  "_seedOrigin" TEXT
);

-- portfolio_skills

CREATE TABLE IF NOT EXISTS "portfolio_skills" (
  "no" TEXT,
  "kicker" TEXT,
  "title" TEXT,
  "desc" TEXT,
  "rows" TEXT CHECK ("rows" IS NULL OR json_valid("rows")),
  "bg" TEXT,
  "fg" TEXT,
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

-- portfolio_folders

CREATE TABLE IF NOT EXISTS "portfolio_folders" (
  "id" TEXT PRIMARY KEY,
  "en" TEXT CHECK ("en" IS NULL OR json_valid("en")),
  "cn" TEXT,
  "bg" TEXT,
  "fg" TEXT,
  "cnFg" TEXT,
  "x" INTEGER,
  "y" INTEGER,
  "rot" INTEGER,
  "z" INTEGER,
  "_seedOrigin" TEXT
);

-- portfolio_posters

CREATE TABLE IF NOT EXISTS "portfolio_posters" (
  "src" TEXT,
  "title" TEXT,
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

-- portfolio_photos

CREATE TABLE IF NOT EXISTS "portfolio_photos" (
  "value" TEXT,
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

-- portfolio_videos

CREATE TABLE IF NOT EXISTS "portfolio_videos" (
  "no" TEXT,
  "en" TEXT,
  "cn" TEXT,
  "desc" TEXT,
  "cover" TEXT,
  "href" TEXT,
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

-- portfolio_websites

CREATE TABLE IF NOT EXISTS "portfolio_websites" (
  "no" TEXT,
  "slug" TEXT,
  "title" TEXT CHECK ("title" IS NULL OR json_valid("title")),
  "kicker" TEXT,
  "desc" TEXT,
  "cover" TEXT,
  "glow" TEXT,
  "href" TEXT,
  "id" TEXT PRIMARY KEY,
  "_seedOrigin" TEXT
);

-- portfolio_seed_notes

CREATE TABLE IF NOT EXISTS "portfolio_seed_notes" (
  "id" TEXT PRIMARY KEY,
  "text" TEXT,
  "color" TEXT,
  "x" INTEGER,
  "y" INTEGER,
  "rot" INTEGER,
  "_seedOrigin" TEXT
);

-- portfolio_config

CREATE TABLE IF NOT EXISTS "portfolio_config" (
  "id" TEXT PRIMARY KEY,
  "value" TEXT CHECK ("value" IS NULL OR json_valid("value")),
  "_seedOrigin" TEXT
);

-- 资源清单；保留授权待确认状态

CREATE TABLE IF NOT EXISTS "asset_manifest" (
  "id" TEXT PRIMARY KEY,
  "url" TEXT,
  "kind" TEXT,
  "group" TEXT,
  "blocking" INTEGER CHECK ("blocking" IN (0, 1) OR "blocking" IS NULL),
  "preload" INTEGER CHECK ("preload" IN (0, 1) OR "preload" IS NULL),
  "bytes" INTEGER,
  "decode" TEXT,
  "fallback" TEXT,
  "onFail" TEXT,
  "timeoutMs" INTEGER,
  "license" TEXT,
  "version" TEXT,
  "variants" TEXT CHECK ("variants" IS NULL OR json_valid("variants")),
  "_seedOrigin" TEXT
);

-- public 文件路径与字节数，媒体文件仍存磁盘

CREATE TABLE IF NOT EXISTS "static_assets" (
  "id" TEXT PRIMARY KEY,
  "url" TEXT,
  "name" TEXT,
  "bytes" INTEGER,
  "extension" TEXT,
  "origin" TEXT,
  "_seedOrigin" TEXT
);

-- ai_conversations

CREATE TABLE IF NOT EXISTS "ai_conversations" (
  "id" INTEGER PRIMARY KEY,
  "name" TEXT NOT NULL,
  "messages" TEXT CHECK ("messages" IS NULL OR json_valid("messages")),
  "userId" TEXT REFERENCES "users"("id"),
  "_seedOrigin" TEXT
);

CREATE INDEX IF NOT EXISTS "idx_ai_conversations_userId" ON "ai_conversations" ("userId");

-- ai_messages

CREATE TABLE IF NOT EXISTS "ai_messages" (
  "role" TEXT NOT NULL CHECK ("role" IN ('user', 'assistant')),
  "text" TEXT NOT NULL,
  "conversationId" INTEGER REFERENCES "ai_conversations"("id"),
  "position" INTEGER,
  "_seedOrigin" TEXT,
  "id" TEXT PRIMARY KEY,
  UNIQUE ("conversationId", "position")
);

CREATE INDEX IF NOT EXISTS "idx_ai_messages_conversationId" ON "ai_messages" ("conversationId");

-- feature_flags

CREATE TABLE IF NOT EXISTS "feature_flags" (
  "id" TEXT PRIMARY KEY,
  "enabled" INTEGER CHECK ("enabled" IN (0, 1) OR "enabled" IS NULL),
  "_seedOrigin" TEXT
);

-- search_history

CREATE TABLE IF NOT EXISTS "search_history" (
  "userId" TEXT REFERENCES "users"("id"),
  "query" TEXT,
  "searchedAt" TEXT,
  "_seedOrigin" TEXT,
  "id" TEXT PRIMARY KEY
);

CREATE INDEX IF NOT EXISTS "idx_search_history_userId" ON "search_history" ("userId");

-- 原始导出/静态常量/Store 快照，无损 JSON 档案

CREATE TABLE IF NOT EXISTS "source_variables" (
  "id" TEXT PRIMARY KEY,
  "source" TEXT,
  "variable" TEXT,
  "value" TEXT CHECK ("value" IS NULL OR json_valid("value")),
  "origin" TEXT,
  "_seedOrigin" TEXT
);

-- 源码 interface 字段名、类型、可选性

CREATE TABLE IF NOT EXISTS "source_models" (
  "id" TEXT PRIMARY KEY,
  "fields" TEXT CHECK ("fields" IS NULL OR json_valid("fields")),
  "_seedOrigin" TEXT
);

COMMIT;
